def acceptance_status(user: dict) -> dict:
    acc = user.get("legal_acceptance") or {}
    return {
        "terms_version": acc.get("terms_version"), "privacy_version": acc.get("privacy_version"),
        "accepted_at": acc["accepted_at"].isoformat() if hasattr(acc.get("accepted_at"), "isoformat") else acc.get("accepted_at"),
        "current_terms_version": TERMS_VERSION, "current_privacy_version": PRIVACY_VERSION,
        "update_required": acc.get("terms_version") != TERMS_VERSION or acc.get("privacy_version") != PRIVACY_VERSION,
    }
